mapper.select:


    inner join sys_user u on u.user_name = ttaskwcsdetail.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    ttaskwcsdetail.del_flag = '0'
    and ttaskwcsdetail.task_id = #{taskId}
    and ttaskwcsdetail.type = #{type}
    and ttaskwcsdetail.origin_id = #{originId}


${params.dataScope}
